urity-page .account-form-grid{grid-template-columns:1fr}.security-page .form-field-full{grid-column:auto}.security-page .form-actions{flex-direction:column}.security-page .form-actions>*{width:100%}}</style><script>document.querySelectorAll('[data-password-toggle]').forEach(function(btn){btn.addEventListener('click',function(){var input=document.getElementById(btn.dataset.passwordToggle),icon=btn.querySelector('i'),visible=input.type==='text';input.type=visible?'password':'text';icon.className=visible?'fas fa-eye':'fas fa-eye-slash';btn.setAttribute('aria-label',(visible?'Show ':'Hide ')+input.name.replaceAll('_',' '));});});var n=document.getElementById('new_password');if(n){var rules={length:function(v){return v.length>=8},letter:function(v){return /[A-Za-z]/.test(v)},number:function(v){return /\d/.test(v)}};n.addEventListener('input',function(){Object.keys(rules).forEach(function(k){var el=document.querySelector('[data-rule="'+k+'"]');el.classList.toggle('is-valid',rules[k](n.value));});});}</script>
